import json,re
from collections import Counter,defaultdict
pat=re.compile(r"(?<![a-z0-9])(book|books|ebook|e-book|novel|textbook|cookbook|manga|comics?)\b", re.IGNORECASE)
counts=Counter()
cats=defaultdict(list)
forbidden_patterns=[r'macbook',r'bookbag',r'bookcase',r'notebook',r'checkbook']
with open('data/products.jsonl',encoding='utf-8') as f:
    for line in f:
        try:
            obj=json.loads(line)
        except:
            continue
        text=((obj.get('name') or '')+' '+(obj.get('description') or '')).lower()
        if not pat.search(text):
            continue
        if any(re.search(fp,text) for fp in forbidden_patterns):
            continue
        match_tokens=pat.findall(text)
        for t in set(match_tokens):
            counts[t.lower()]+=1
        pid=obj.get('product_id')
        title=(obj.get('name') or '').strip()
        if re.search(r'\b(?:comic|manga|mangas)\b',text):
            cats['comics'].append((pid,title))
        if re.search(r'\b(?:novel)\b',text):
            cats['novels'].append((pid,title))
        if re.search(r'\b(?:textbook|text book)\b',text):
            cats['textbooks'].append((pid,title))
        if re.search(r'\b(?:cookbook|cooking)\b',text):
            cats['cookbooks'].append((pid,title))
        if re.search(r'\b(?:e-book|ebook|kindle|kindle ebook|pdf)\b',text):
            cats['digital_books'].append((pid,title))
        if re.search(r'\b(?:journal|diary|notebook|notebooks)\b',text):
            cats['notebooks'].append((pid,title))
        if re.search(r'\b(?:audio book|audiobook)\b',text):
            cats['audiobook'].append((pid,title))
        if re.search(r'\b(?:magazine|magazines|journal|periodical)\b',text):
            cats['magazines'].append((pid,title))

print('token_counts')
for k,v in counts.most_common():
    print(k,v)
print('\ncategory sample sizes')
for k,v in cats.items():
    if v:
        print(k,len(v))
        for pid,title in v[:8]:
            print(' ',pid, title[:120])
