            if rx.search(text):
                hits.append(p.strip('\\b'))
        if hits:
            collect.setdefault(tuple(sorted(hits)),[]).append((o.get('product_id'),o.get('name')))

print('clusters',len(collect))
for k,v in sorted(collect.items(), key=lambda x: -len(x[1]))[:30]:
    print('\n',k,'count',len(v))
    for pid,name in v[:6]:
        print(' ',pid,name)
